{
  "name": "@rockysoft/opencode-hybrid-workflow",
  "version": "1.7.0",
  "description": "Portable configurable-reviewer planning, design, implementation checkpoints and usage sidebar for OpenCode 2",
  "type": "module",
  "license": "MIT",
  "author": "RockySoft",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agents",
    "code-review",
    "workflow"
  ],
  "publishConfig": {
    "access": "public",
    "tag": "latest"
  },
  "exports": {
    ".": "./index.js",
    "./tui": "./tui.js"
  },
  "bin": {
    "opencode-hybrid": "./cli.mjs"
  },
  "files": [
    "index.js",
    "tui.js",
    "cli.mjs",
    "lib/",
    "core/",
    "sidebar/",
    "assets/",
    "README.md",
    "THIRD_PARTY_NOTICES.md",
    "LICENSE",
    "docs/"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "prepack": "npm run build",
    "test": "node --test test/*.test.mjs",
    "doctor": "node cli.mjs doctor"
  },
  "devDependencies": {
    "@babel/core": "7.29.7",
    "@babel/preset-typescript": "7.27.1",
    "babel-preset-solid": "1.9.12"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.1.2 <3",
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "dependencies": {
    "diff": "9.0.0"
  }
}
